// Process-wide immutable session profile. Installation is validate-then-swap.
public static class ContentTuning {
 sealed class Entry {public string id,type,value;public bool literalDefault;public double min,max;}
 static Dictionary<string,Entry> catalog=new Dictionary<string,Entry>(StringComparer.Ordinal);
 static volatile Dictionary<string,string> active=new Dictionary<string,string>(StringComparer.Ordinal);
 static int schemaVersion=1;public static int SchemaVersion {get{return schemaVersion;}}
 static string snapshot;static readonly object gate=new object();
 static void Members(Dictionary<string,object> d,params string[] names){foreach(string k in d.Keys)if(Array.IndexOf(names,k)<0)throw new ArgumentException("Unknown JSON member "+k);foreach(string k in names)if(!d.ContainsKey(k))throw new ArgumentException("Missing JSON member "+k);}
 static string Str(object o){var s=o as string;if(s==null)throw new ArgumentException("Expected string");return s;}
 static int Integer(object o){if(!(o is double)||((double)o)%1!=0||(double)o<0||(double)o>2147483647)throw new ArgumentException("Expected nonnegative integer");return (int)(double)o;}
 static double Numeric(string s){double n;if(s.Length==0||s.Trim()!=s||!double.TryParse(s,NumberStyles.Float,CultureInfo.InvariantCulture,out n)||double.IsNaN(n)||double.IsInfinity(n))throw new ArgumentException("Expected finite number");return n;}
 static void ValidateValue(Entry e,string value){if(e.type=="text"){if(e.id=="passenger.presets"){PassengerPresetCatalog.Parse(value);return;}if(value.Length>4000)throw new ArgumentException("Text too long "+e.id);return;}if(e.type=="boolean"){if(value!="true"&&value!="false")throw new ArgumentException("Expected boolean "+e.id);return;}double n=Numeric(value);if(n<e.min||n>e.max||e.type=="integer"&&n%1!=0)throw new ArgumentException("Out of range "+e.id);}
 public static void ValidateOverride(string id,string value){Entry e;if(!catalog.TryGetValue(id,out e))throw new ArgumentException("Unknown override key "+id);if(value==null||e.type=="text"&&value.Trim().Length==0)throw new ArgumentException("Empty override value");ValidateValue(e,value);}
 public static void ConfigureCatalog(string json){var root=ContentJson.Object(ContentJson.Parse(json));foreach(string k in root.Keys)if(k!="schemaVersion"&&k!="entries"&&k!="references"&&k!="literalReplyIds")throw new ArgumentException("Unknown catalog member "+k);if(!root.ContainsKey("schemaVersion")||Integer(root["schemaVersion"])!=1||!root.ContainsKey("entries"))throw new ArgumentException("Unsupported catalog");var allIds=new HashSet<string>(StringComparer.Ordinal);var next=new Dictionary<string,Entry>(StringComparer.Ordinal);foreach(object o in ContentJson.Array(root["entries"])){var row=ContentJson.Object(o);Members(row,"id","group","section","title","type","defaultValue","min","max","unit","description","affects","modes","status","consumer","editable");string id=Str(row["id"]);if(!allIds.Add(id)||id.Length==0||id.Length>160)throw new ArgumentException("Invalid catalog ID");foreach(char c in id)if(c>127||!(char.IsLetterOrDigit(c)||c=='.'||c=='_'||c=='-'))throw new ArgumentException("Invalid catalog ID");if(!(row["editable"] is bool))throw new ArgumentException("Invalid editable flag");if(!(bool)row["editable"])continue;var e=new Entry{id=id,type=Str(row["type"]),value=Str(row["defaultValue"]),min=Convert.ToDouble(row["min"],CultureInfo.InvariantCulture),max=Convert.ToDouble(row["max"],CultureInfo.InvariantCulture)};if(e.type!="number"&&e.type!="integer"&&e.type!="text"&&e.type!="boolean"||next.ContainsKey(id)||e.min>e.max||Str(row["consumer"]).Length==0)throw new ArgumentException("Invalid catalog entry "+id);if(id!="passenger.presets")ValidateValue(e,e.value);next.Add(id,e);}if(root.ContainsKey("literalReplyIds"))foreach(object item in ContentJson.Array(root["literalReplyIds"])){Entry literal;string key=Str(item);if(!next.TryGetValue(key,out literal)||literal.type!="text"||!key.StartsWith("request.",StringComparison.Ordinal)||key.IndexOf(".reply.",StringComparison.Ordinal)<0||literal.literalDefault)throw new ArgumentException("Invalid literal reply "+key);literal.literalDefault=true;}foreach(var entry in next.Values)if(entry.id=="passenger.presets")PassengerPresetCatalog.Parse(entry.value,(id,value)=>{Entry target;if(!next.TryGetValue(id,out target))throw new ArgumentException("Unknown override key");if(target.type=="text"&&value.Trim().Length==0)throw new ArgumentException("Empty override text");ValidateValue(target,value);});var defaults=new Dictionary<string,string>(StringComparer.Ordinal);foreach(var e in next.Values)defaults.Add(e.id,e.value);Relations(defaults);lock(gate){catalog=next;UseDefaults();}}
 static Dictionary<string,object> Profile(string id,int revision,Dictionary<string,string> vals,int version){var rows=new List<object>();var keys=new List<string>(vals.Keys);keys.Sort(StringComparer.Ordinal);foreach(string k in keys)rows.Add(new Dictionary<string,object>{{"id",k},{"value",vals[k]}});var p=new Dictionary<string,object>{{"schemaVersion",(double)version},{"id",id},{"revision",(double)revision},{"contentHash",""},{"values",rows}};p["contentHash"]=ComputeHash(p);return p;}
 public static string ComputeHash(Dictionary<string,object> p){var vals=new SortedDictionary<string,string>(StringComparer.Ordinal);foreach(object o in ContentJson.Array(p["values"])){var row=ContentJson.Object(o);string id=Str(row["id"]);if(vals.ContainsKey(id))throw new ArgumentException("Duplicate value "+id);vals.Add(id,Str(row["value"]));}var b=new StringBuilder("content-profile-v"+Integer(p["schemaVersion"]).ToString(CultureInfo.InvariantCulture)+"\n");b.Append(Str(p["id"])).Append('\n').Append(Integer(p["revision"]).ToString(CultureInfo.InvariantCulture)).Append('\n');foreach(var row in vals)b.Append(row.Key).Append('\t').Append(Encoding.UTF8.GetByteCount(row.Value).ToString(CultureInfo.InvariantCulture)).Append(':').Append(row.Value).Append('\n');using(var sha=SHA256.Create()){byte[] hash=sha.ComputeHash(new UTF8Encoding(false,true).GetBytes(b.ToString()));var hex=new StringBuilder();foreach(byte x in hash)hex.Append(x.ToString("x2"));return hex.ToString();}}
 static Dictionary<string,string> Decode(string json,out string canonical){if(Encoding.UTF8.GetByteCount(json)>240*1024)throw new ArgumentException("Profile too large");var p=ContentJson.Object(ContentJson.Parse(json));Members(p,"schemaVersion","id","revision","contentHash","values");int version=Integer(p["schemaVersion"]);if((version!=1&&version!=2)||Integer(p["revision"])<1)throw new ArgumentException("Unsupported profile");string id=Str(p["id"]);if(id.Length<1||id.Length>64)throw new ArgumentException("Invalid profile id");foreach(char c in id)if(!(c>='a'&&c<='z'||c>='A'&&c<='Z'||c>='0'&&c<='9'||c=='_'||c=='-'))throw new ArgumentException("Invalid profile id");var vals=new Dictionary<string,string>(StringComparer.Ordinal);foreach(object o in ContentJson.Array(p["values"])){var row=ContentJson.Object(o);Members(row,"id","value");string key=Str(row["id"]),v=Str(row["value"]);Entry entry;if(version==1&&key.StartsWith("choice.",StringComparison.Ordinal)||!catalog.TryGetValue(key,out entry)||vals.ContainsKey(key))throw new ArgumentException("Unknown/duplicate setting "+key);ValidateValue(entry,v);vals.Add(key,v);}bool oldDrunk=true;foreach(string key in vals.Keys)if(IsDrunkSetting(key))oldDrunk=false;int expected=0;foreach(string key in catalog.Keys)if((version==2||!key.StartsWith("choice.",StringComparison.Ordinal))&&!(oldDrunk&&IsDrunkSetting(key))&&!(key=="passenger.presets"&&!vals.ContainsKey(key)))expected++;if(vals.Count!=expected)throw new ArgumentException("Incomplete profile");if(Str(p["contentHash"])!=ComputeHash(p))throw new ArgumentException("Content hash mismatch");if(vals.ContainsKey("passenger.presets")&&(!vals.ContainsKey("choice.effects.version")||vals["choice.effects.version"]!="1"))foreach(var preset in PassengerPresetCatalog.Parse(vals["passenger.presets"]))foreach(var row in preset.overrides)if(row.id.StartsWith("choice.",StringComparison.Ordinal))throw new ArgumentException("Choice overrides require enabled schema2 effects");Relations(vals);canonical=ContentJson.Stringify(Profile(id,Integer(p["revision"]),vals,version));return vals;}
 static void Relations(Dictionary<string,string> v){if(v.ContainsKey("schedule.count0")&&Numeric(v["schedule.count0"])+Numeric(v["schedule.count1"])+Numeric(v["schedule.count2"])!=100)throw new ArgumentException("Request count weights must total 100");if(v.ContainsKey("schedule.progressMin")&&(Numeric(v["schedule.progressMin"])>Numeric(v["schedule.progressMax"])||Numeric(v["schedule.progressMax"])>=Numeric(v["schedule.cutoff"])))throw new ArgumentException("Invalid progress window");if(v.ContainsKey("common.required.easy")&&(Numeric(v["common.required.easy"])>Numeric(v["common.required.normal"])||Numeric(v["common.required.normal"])>Numeric(v["common.required.hard"])))throw new ArgumentException("Required satisfaction must be ordered");foreach(string prefix in new[]{"request.","type."}){bool found=false;double total=0;foreach(var row in v)if(row.Key.StartsWith(prefix,StringComparison.Ordinal)&&row.Key.EndsWith(".weight",StringComparison.Ordinal)){found=true;string enabled=row.Key.Substring(0,row.Key.Length-6)+"enabled";if(!v.ContainsKey(enabled)||v[enabled]=="true")total+=Numeric(row.Value);}if(found&&total<=0)throw new ArgumentException("No enabled weighted candidates "+prefix);}}
 public static void UseDefaults(){lock(gate){var vals=new Dictionary<string,string>(StringComparer.Ordinal);foreach(var e in catalog.Values)vals.Add(e.id,e.value);schemaVersion=catalog.ContainsKey("choice.effects.version")?2:1;active=vals;snapshot=ContentJson.Stringify(Profile("default",1,vals,schemaVersion));}}
 public static void ValidateJson(string json){lock(gate){string c;Decode(json,out c);}}
 public static void UseJson(string json){lock(gate){string c;var vals=Decode(json,out c);schemaVersion=Integer(ContentJson.Object(ContentJson.Parse(c))["schemaVersion"]);active=vals;snapshot=c;}}
 static bool IsDrunkSetting(string key){return key=="type.Drunk.spawnPercent"||key=="type.Drunk.dailyMax"||key=="type.Drunk.forceEnabled"||key=="type.Drunk.forceAfterMisses"||key=="type.Drunk.sleepPercent"||key=="type.Drunk.vomitPercent";}
 public static string UpgradeJson(string json){lock(gate){string canonical;var vals=Decode(json,out canonical);var p=ContentJson.Object(ContentJson.Parse(canonical));foreach(var e in catalog.Values)if((IsDrunkSetting(e.id)||e.id=="passenger.presets")&&!vals.ContainsKey(e.id))vals.Add(e.id,e.value);if(Integer(p["schemaVersion"])==2||!catalog.ContainsKey("choice.effects.version"))return ContentJson.Stringify(Profile(Str(p["id"]),Integer(p["revision"]),vals,Integer(p["schemaVersion"])));foreach(var e in catalog.Values)if(e.id.StartsWith("choice.",StringComparison.Ordinal)){string value="0";if(e.id=="choice.effects.version")value="1";else if(e.id=="choice.type.Food.1.immediate.satisfaction")value=vals["effect.food.satisfaction"];else if(e.id=="choice.request.Comfort.Accept.during.motionPenaltyDelta")value=(Numeric(vals["manner.comfortMotion.penalty"])-Numeric(vals["manner.motion.penalty"])).ToString("R",CultureInfo.InvariantCulture);else {string[] parts=e.id.Split('.');if(parts.Length==7&&parts[1]=="request"&&parts[3]!="Defer"&&parts[2]!="Eta"&&parts[2]!="RejectIllegal"&&parts[4]=="end"&&(parts[5]=="success"||parts[5]=="failure")&&parts[6]=="satisfaction")value=vals["request."+parts[2]+"."+parts[5]];}ValidateValue(e,value);vals.Add(e.id,value);}string result=ContentJson.Stringify(Profile(Str(p["id"]),Integer(p["revision"]),vals,2));string checkedCanonical;Decode(result,out checkedCanonical);return checkedCanonical;}}
 public static string CaptureJson(){lock(gate){if(snapshot==null)UseDefaults();return snapshot;}}
 public static double Number(string id,double fallback){string value;return active.TryGetValue(id,out value)?Numeric(value):fallback;}
 public static int Int(string id,int fallback){return (int)Number(id,fallback);}
 public static string Text(string id,string fallback){string v;return active.TryGetValue(id,out v)&&v.Length>0?v:fallback;}
 public static string OverrideText(string id,string fallback){string value;Entry entry;return active.TryGetValue(id,out value)&&catalog.TryGetValue(id,out entry)&&value.Length>0&&(value!=entry.value||entry.literalDefault)?value:fallback;}
 public static bool Flag(string id,bool fallback){string v;return active.TryGetValue(id,out v)?v=="true":fallback;}
}
// Pure JSON contract, deliberately independent of Unity and the legacy action enum.
[Serializable] public sealed class PassengerPresetDefinition {
 public string id,name,pool,intro;
 public bool enabled;
 public int weight;
 public string[] traits;
 public PassengerOverride[] overrides=new PassengerOverride[0];
 public bool Has(string trait){return Array.IndexOf(traits,trait)>=0;}
 public string RepresentativeModule {get{foreach(string t in traits)if(t=="body.sensitive"||t.StartsWith("purpose.",StringComparison.Ordinal))return PassengerPresetCatalog.Module(t);return "General";}}
 public string ActionModule {get{foreach(string t in traits)if(t=="body.sleepy"||t=="speech.talkative"||t.StartsWith("item.",StringComparison.Ordinal))return PassengerPresetCatalog.Module(t);string r=RepresentativeModule;return r!="General"?r:Has("body.drunk")?"Drunk":"General";}}
}
public static class PassengerPresetCatalog {
 static readonly string[] pools={"General","Drunk","Sleeping","Comfort","Hurried","RouteChecking","Errand","Luggage","MuddyLuggage","Food","PrecisionStop","Talkative"};
 static readonly string[] traits={"speech.quiet","body.drunk","body.sleepy","body.sensitive","purpose.hurried","purpose.route","purpose.errand","item.luggage","item.muddy","item.food","purpose.precise","speech.talkative"};
 public static string Module(string trait){int i=Array.IndexOf(traits,trait);if(i<0)throw new ArgumentException("Unknown passenger trait "+trait);return pools[i];}
 static void Members(Dictionary<string,object> row,params string[] names){if(row.Count!=names.Length)throw new ArgumentException("Invalid preset members");foreach(string n in names)if(!row.ContainsKey(n))throw new ArgumentException("Missing preset member "+n);}
 static string Text(object value,int min,int max){string s=value as string;if(s==null||s.Length<min||s.Length>max)throw new ArgumentException("Invalid preset text");return s;}
 public static void Validate(PassengerPresetDefinition p,Action<string,string> validateOverride=null){
  if(p==null||p.traits==null)throw new ArgumentException("Missing passenger preset");Text(p.id,1,48);Text(p.name,1,60);Text(p.intro,0,240);if(p.name.Trim().Length==0)throw new ArgumentException("Blank preset name");
  foreach(char c in p.id)if(!(c>='a'&&c<='z'||c>='0'&&c<='9'||c=='_'||c=='-'))throw new ArgumentException("Invalid preset id");
  if(Array.IndexOf(pools,p.pool)<0||p.weight<0||p.weight>100)throw new ArgumentException("Invalid preset pool/weight");
  var seen=new HashSet<string>(StringComparer.Ordinal);int representative=0,primary=0;
  foreach(string t in p.traits){if(Array.IndexOf(traits,t)<0||!seen.Add(t))throw new ArgumentException("Unknown/duplicate passenger trait");if(t=="body.sensitive"||t.StartsWith("purpose.",StringComparison.Ordinal))representative++;if(t=="body.sleepy"||t=="speech.talkative"||t.StartsWith("item.",StringComparison.Ordinal))primary++;}
  if(representative>1||primary>1)throw new ArgumentException("Only one action and one representative request are supported");
  if(p.Has("speech.quiet")&&p.Has("speech.talkative")||p.Has("body.drunk")&&p.Has("body.sleepy"))throw new ArgumentException("Conflicting passenger traits");
  if(p.Has("body.drunk")!=(p.pool=="Drunk"))throw new ArgumentException("Drunk trait requires Drunk pool and vice versa");
  if(p.pool=="General"&&(p.traits.Length>1||p.traits.Length==1&&!p.Has("speech.quiet")))throw new ArgumentException("General rest pool supports only quiet");
  if(p.overrides==null||p.overrides.Length>128)throw new ArgumentException("Invalid override count");var overrideIds=new HashSet<string>(StringComparer.Ordinal);foreach(var row in p.overrides){if(row==null||row.id==null||row.value==null||!overrideIds.Add(row.id)||!Allowed(p,row.id))throw new ArgumentException("Invalid passenger override");(validateOverride??ContentTuning.ValidateOverride)(row.id,row.value);}

 }
 public static bool Allowed(PassengerPresetDefinition p,string id){
  string action=p.ActionModule;
  if(id.StartsWith("type."+action+".intro.",StringComparison.Ordinal)||id.StartsWith("type."+action+".choice.",StringComparison.Ordinal)||id.StartsWith("type."+action+".followup.",StringComparison.Ordinal)||id.StartsWith("choice.type."+action+".",StringComparison.Ordinal)||action=="Sleeping"&&id.StartsWith("choice.type.SleepingFollowup.",StringComparison.Ordinal))return true;
  if(id.StartsWith("request.",StringComparison.Ordinal)&&(id.EndsWith(".prompt",StringComparison.Ordinal)||id.EndsWith(".unanswered",StringComparison.Ordinal)||id.IndexOf(".reply.",StringComparison.Ordinal)>=0)||id.StartsWith("choice.request.",StringComparison.Ordinal)||id.StartsWith("situation.",StringComparison.Ordinal)&&id.IndexOf(".reply.",StringComparison.Ordinal)>=0||id.StartsWith("choice.situation.",StringComparison.Ordinal))return true;
  return p.Has("item.food")&&id.StartsWith("effect.food.",StringComparison.Ordinal)&&id!="effect.food.satisfaction"||p.Has("item.luggage")&&id.StartsWith("effect.luggage.",StringComparison.Ordinal)||p.Has("item.muddy")&&id.StartsWith("effect.muddy.",StringComparison.Ordinal)||p.Has("body.sleepy")&&id=="effect.sleep.calmSeconds"||(p.Has("item.luggage")||p.Has("item.muddy"))&&id=="effect.resecure.seconds"||p.Has("purpose.errand")&&id=="effect.errand.seconds"||p.Has("body.drunk")&&(id=="type.Drunk.sleepPercent"||id=="type.Drunk.vomitPercent");
 }
 public static PassengerPresetDefinition[] Parse(string json,Action<string,string> validateOverride=null){
  if(json==null||json.Length>32000)throw new ArgumentException("Passenger presets exceed 32000 characters");
  var root=ContentJson.Object(ContentJson.Parse(json));Members(root,"version","presets");if(!(root["version"] is double)||((double)root["version"]!=1&&(double)root["version"]!=2))throw new ArgumentException("Unsupported passenger preset version");
  var rows=ContentJson.Array(root["presets"]);if(rows.Count>32)throw new ArgumentException("At most32 passenger presets");var result=new List<PassengerPresetDefinition>();var ids=new HashSet<string>(StringComparer.Ordinal);
  foreach(object o in rows){var row=ContentJson.Object(o);if((double)root["version"]==1)Members(row,"id","name","enabled","weight","pool","traits","intro");else Members(row,"id","name","enabled","weight","pool","traits","intro","overrides");if(!(row["enabled"] is bool)||!(row["weight"] is double))throw new ArgumentException("Invalid preset enabled/weight");double weight=(double)row["weight"];if(weight<0||weight>100||weight%1!=0)throw new ArgumentException("Invalid preset weight");var list=new List<string>();foreach(object t in ContentJson.Array(row["traits"]))list.Add(Text(t,1,48));var p=new PassengerPresetDefinition{id=Text(row["id"],1,48),name=Text(row["name"],1,60),enabled=(bool)row["enabled"],weight=(int)weight,pool=Text(row["pool"],1,48),traits=list.ToArray(),intro=Text(row["intro"],0,240)};if((double)root["version"]==2){var overrides=new List<PassengerOverride>();foreach(object item in ContentJson.Array(row["overrides"])){var itemRow=ContentJson.Object(item);Members(itemRow,"id","value");overrides.Add(new PassengerOverride{id=Text(itemRow["id"],1,160),value=Text(itemRow["value"],0,4000)});}p.overrides=overrides.ToArray();}Validate(p,validateOverride);if(!ids.Add(p.id))throw new ArgumentException("Duplicate preset id");result.Add(p);}
  result.Sort((a,b)=>StringComparer.Ordinal.Compare(a.id,b.id));return result.ToArray();
 }
}

[Serializable] public sealed class PassengerOverride {public string id,value;}
// Immutable copied rider values; shared fallbacks never mutate the session profile.
public sealed class PassengerContent {
 readonly PassengerOverride[] rows;
 public static readonly PassengerContent Shared=new PassengerContent(null);
 public PassengerContent(PassengerOverride[] values){rows=Clone(values);}
 public static PassengerOverride[] Clone(PassengerOverride[] values){if(values==null)return new PassengerOverride[0];return Array.ConvertAll(values,x=>x==null?null:new PassengerOverride{id=x.id,value=x.value});}
 public PassengerOverride[] Capture(){return Clone(rows);}
 bool Find(string id,out string value){foreach(var row in rows)if(row.id==id){value=row.value;return true;}value=null;return false;}
 public double Number(string id,double fallback){string value;return Find(id,out value)?double.Parse(value,CultureInfo.InvariantCulture):ContentTuning.Number(id,fallback);}
 public int Int(string id,int fallback){return (int)Number(id,fallback);}
 public string Text(string id,string fallback){string value;return Find(id,out value)?value:ContentTuning.Text(id,fallback);}
 public string OverrideText(string id,string fallback){string value;return Find(id,out value)?value:ContentTuning.OverrideText(id,fallback);}
}
